import sys

try:
    sys.set_int_max_str_digits(0)
except Exception:
    pass


def parse_json(text: str) -> object:
    t = text
    n = len(t)

    def skip_ws(i: int) -> int:
        while i < n:
            c = t[i]
            if c == " " or c == "\t" or c == "\n" or c == "\r":
                i += 1
            else:
                break
        return i

    def parse_hex4(pos: int) -> tuple[int, int]:
        if pos + 4 > n:
            raise ValueError

        val = 0
        for k in range(4):
            o = ord(t[pos + k])
            if 48 <= o <= 57:
                d = o - 48
            elif 65 <= o <= 70:
                d = o - 55
            elif 97 <= o <= 102:
                d = o - 87
            else:
                raise ValueError
            val = (val << 4) | d

        return val, pos + 4

    def parse_string(i: int) -> tuple[str, int]:
        if i >= n or t[i] != '"':
            raise ValueError

        i += 1
        out = []
        start = i

        while i < n:
            c = t[i]

            if c == '"':
                if start < i:
                    out.append(t[start:i])
                return "".join(out), i + 1

            if c == "\\":
                if start < i:
                    out.append(t[start:i])

                i += 1
                if i >= n:
                    raise ValueError

                e = t[i]
                if e == '"':
                    out.append('"')
                    i += 1
                elif e == "\\":
                    out.append("\\")
                    i += 1
                elif e == "/":
                    out.append("/")
                    i += 1
                elif e == "b":
                    out.append("\b")
                    i += 1
                elif e == "f":
                    out.append("\f")
                    i += 1
                elif e == "n":
                    out.append("\n")
                    i += 1
                elif e == "r":
                    out.append("\r")
                    i += 1
                elif e == "t":
                    out.append("\t")
                    i += 1
                elif e == "u":
                    cp, ni = parse_hex4(i + 1)
                    i = ni

                    if 0xD800 <= cp <= 0xDBFF:
                        if i + 6 > n:
                            raise ValueError
                        if t[i] != "\\" or t[i + 1] != "u":
                            raise ValueError

                        low_cp, ni = parse_hex4(i + 2)
                        i = ni

                        if not (0xDC00 <= low_cp <= 0xDFFF):
                            raise ValueError

                        cp = 0x10000 + ((cp - 0xD800) << 10) + (low_cp - 0xDC00)
                        out.append(chr(cp))
                    elif 0xDC00 <= cp <= 0xDFFF:
                        raise ValueError
                    else:
                        out.append(chr(cp))
                else:
                    raise ValueError

                start = i
                continue

            o = ord(c)
            if o < 32:
                raise ValueError

            if 0xD800 <= o <= 0xDFFF:
                if 0xD800 <= o <= 0xDBFF and i + 1 < n:
                    o2 = ord(t[i + 1])
                    if 0xDC00 <= o2 <= 0xDFFF:
                        if start < i:
                            out.append(t[start:i])
                        cp = 0x10000 + ((o - 0xD800) << 10) + (o2 - 0xDC00)
                        out.append(chr(cp))
                        start = i + 2
                        i = start
                        continue
                raise ValueError

            i += 1

        raise ValueError

    def parse_number(i: int) -> tuple[object, int]:
        start = i

        if t[i] == "-":
            i += 1

        if i >= n:
            raise ValueError

        c = t[i]
        if c == "0":
            i += 1
            if i < n and 48 <= ord(t[i]) <= 57:
                raise ValueError
        elif 48 <= ord(c) <= 57:
            i += 1
            while i < n and 48 <= ord(t[i]) <= 57:
                i += 1
        else:
            raise ValueError

        has_frac = False
        has_exp = False

        if i < n and t[i] == ".":
            has_frac = True
            i += 1
            if i >= n or not (48 <= ord(t[i]) <= 57):
                raise ValueError
            while i < n and 48 <= ord(t[i]) <= 57:
                i += 1

        if i < n and (t[i] == "e" or t[i] == "E"):
            has_exp = True
            i += 1
            if i < n and (t[i] == "+" or t[i] == "-"):
                i += 1
            if i >= n or not (48 <= ord(t[i]) <= 57):
                raise ValueError
            while i < n and 48 <= ord(t[i]) <= 57:
                i += 1

        token = t[start:i]
        if has_frac or has_exp:
            try:
                return float(token), i
            except OverflowError:
                return (float("-inf") if token[0] == "-" else float("inf")), i

        return int(token), i

    def parse_literal(i: int) -> tuple[object, int]:
        c = t[i]
        if c == "t":
            if t.startswith("true", i):
                return True, i + 4
        elif c == "f":
            if t.startswith("false", i):
                return False, i + 5
        elif c == "n":
            if t.startswith("null", i):
                return None, i + 4

        raise ValueError

    def parse_scalar(i: int) -> tuple[object, int]:
        if i >= n:
            raise ValueError

        c = t[i]
        if c == '"':
            return parse_string(i)
        if c == "-" or 48 <= ord(c) <= 57:
            return parse_number(i)
        if c == "t" or c == "f" or c == "n":
            return parse_literal(i)

        raise ValueError

    def is_value_start(c: str) -> bool:
        return (
            c == '"'
            or c == "t"
            or c == "f"
            or c == "n"
            or c == "-"
            or 48 <= ord(c) <= 57
        )

    def apply_value(value: object) -> None:
        parent = stack[-1]
        if parent[0] == 0:
            parent[1].append(value)
            parent[2] = 1
        else:
            key = parent[3]
            if key in parent[1]:
                raise ValueError
            parent[1][key] = value
            parent[3] = None
            parent[2] = 1

    i = skip_ws(0)
    if i >= n:
        raise ValueError

    first = t[i]

    if first == "[":
        stack = [[0, [], 0, None]]
        i += 1
    elif first == "{":
        stack = [[1, {}, 0, None]]
        i += 1
    elif first == '"' or first == "t" or first == "f" or first == "n" or first == "-" or (48 <= ord(first) <= 57):
        value, i = parse_scalar(i)
        i = skip_ws(i)
        if i != n:
            raise ValueError
        return value
    else:
        raise ValueError

    result = None

    while stack:
        kind, container, state, pending_key = stack[-1]
        i = skip_ws(i)
        if i >= n:
            raise ValueError

        c = t[i]

        if kind == 0:  # array
            if state == 0:  # before first element
                if c == "]":
                    i += 1
                    stack.pop()
                    if stack:
                        apply_value(container)
                    else:
                        result = container
                    continue

                if c == "[" or c == "{":
                    if c == "[":
                        stack.append([0, [], 0, None])
                    else:
                        stack.append([1, {}, 0, None])
                    i += 1
                    continue

                if is_value_start(c):
                    value, i = parse_scalar(i)
                    apply_value(value)
                    continue

                raise ValueError

            elif state == 1:  # after element
                if c == "]":
                    i += 1
                    stack.pop()
                    if stack:
                        apply_value(container)
                    else:
                        result = container
                    continue

                if c == ",":
                    stack[-1][2] = 2
                    i += 1
                    continue

                raise ValueError

            else:  # after comma
                if c == "[" or c == "{":
                    if c == "[":
                        stack.append([0, [], 0, None])
                    else:
                        stack.append([1, {}, 0, None])
                    i += 1
                    continue

                if is_value_start(c):
                    value, i = parse_scalar(i)
                    apply_value(value)
                    continue

                raise ValueError

        else:  # object
            if state == 0:  # before first key
                if c == "}":
                    i += 1
                    stack.pop()
                    if stack:
                        apply_value(container)
                    else:
                        result = container
                    continue

                if c == '"':
                    key, i = parse_string(i)
                    i = skip_ws(i)
                    if i >= n or t[i] != ":":
                        raise ValueError
                    stack[-1][2] = 3
                    stack[-1][3] = key
                    i += 1
                    continue

                raise ValueError

            elif state == 1:  # after value
                if c == "}":
                    i += 1
                    stack.pop()
                    if stack:
                        apply_value(container)
                    else:
                        result = container
                    continue

                if c == ",":
                    stack[-1][2] = 2
                    i += 1
                    continue

                raise ValueError

            elif state == 2:  # after comma, expecting key
                if c == '"':
                    key, i = parse_string(i)
                    i = skip_ws(i)
                    if i >= n or t[i] != ":":
                        raise ValueError
                    stack[-1][2] = 3
                    stack[-1][3] = key
                    i += 1
                    continue

                raise ValueError

            else:  # after colon, expecting value
                if c == "[" or c == "{":
                    if c == "[":
                        stack.append([0, [], 0, None])
                    else:
                        stack.append([1, {}, 0, None])
                    i += 1
                    continue

                if is_value_start(c):
                    value, i = parse_scalar(i)
                    apply_value(value)
                    continue

                raise ValueError

    i = skip_ws(i)
    if i != n:
        raise ValueError

    return result
